1	/** Private, pure partial-evidence carrier. Never admission or whole-clause proof. */
2	import { createHash } from "node:crypto";
3	import { types } from "node:util";
4	import { canonicalJson } from "../src/canonical-json.js";
5	import {
6	  ConformanceArtifactBundleError,
7	  copySourceBytes,
8	  parseBoundedJson,
9	  createCumulativeTransactionalArtifactBundle,
10	  type ConformanceArtifactSource,
11	  type ConformanceArtifactBundle,
12	} from "../src/artifact-bundle.js";
13	import {
14	  assertCanonicalProfileContractSelection,
15	  type ProfileContractSelection,
16	} from "../src/profile-contract-selection.js";
17	import { selectApplicableScenariosForProfile } from "../src/selection.js";
18	import {
19	  assertSameServedProfileConfiguration,
20	  ownData,
21	  planProfileExecution,
22	  type ServedProfileConfiguration,
23	} from "./profile-contract-plan.js";
24	import {
25	  assertReadUpdateArtifactSet,
26	  copyReadUpdateArtifactSetSources,
27	  type ReadUpdateArtifactSet,
28	} from "./read-update-artifact-set.js";
29	import { installedContractsDigest } from "../../../apps/bdptest/test-support/installed-contract-identity.js";
30	
31	type Data = Record<string, unknown>;
32	type Artifacts =
33	  | { readonly kind: "read-update"; readonly set: ReadUpdateArtifactSet }
34	  | {
35	      readonly kind: "transactional";
36	      readonly manifest: ConformanceArtifactSource;
37	      readonly fixture: ConformanceArtifactSource;
38	      readonly coverage: ConformanceArtifactSource;
39	    };
40	type Observation = {
41	  readonly ownerId: string;
42	  readonly sourceCommit: string;
43	  readonly configuration: ServedProfileConfiguration;
44	  readonly runtimeConfigurationIdentity: string;
45	  readonly exactConfiguration: unknown;
46	  readonly ready: readonly unknown[];
47	  readonly reportSource: ConformanceArtifactSource;
48	  readonly expectedReportSha256: string;
49	  readonly lifecycle: { readonly cleanup: "pending" | "reported-complete" | "failed" | "unknown" };
50	};
51	type Attempt = {
52	  readonly outcome: "running" | "failed" | "observed";
53	  readonly failureStages: readonly ("execution" | "assertion" | "cleanup" | "credential-check")[];
54	  readonly owners: readonly {
55	    readonly id: string;
56	    readonly status: string;
57	    readonly cleanup: string;
58	    readonly evidence: string;
59	  }[];
60	  readonly sourceDirty: boolean | null;
61	};
62	const assembled = new WeakSet<object>();
63	const MAX_SOURCE = 4194304;
64	const MAX_SUMMARY = 1048576;
65	const LIMITATIONS = [
66	  "source-private carrier only; no public admission or proof token",
67	  "trusted-source identity equality does not prove run truth",
68	  "source/historical/data-unit observations never current installed qualification",
69	  "reported cleanup is not verified child/owner closure",
70	  "final combined basis unbound; incoming startup/D3a not adopted",
71	] as const;
72	const UNRESOLVED = [
73	  "D2-S1-G2",
74	  "D3-cold-listener-admission",
75	  "D4-administration-retained-copies-restore",
76	  "final-combined-source-configuration-installed-provenance",
77	  "whole-governing-clause-review",
78	];
79	class ProfileEvidenceError extends Error {
80	  constructor(readonly code: string) {
81	    super("private profile evidence refused");
82	    this.name = "ProfileEvidenceError";
83	  }
84	}
85	function refuse(code = "invalid-source"): never {
86	  throw new ProfileEvidenceError(code);
87	}
88	function boundary<T>(work: () => T): T {
89	  try {
90	    return work();
91	  } catch (error) {
92	    if (error instanceof ProfileEvidenceError) throw error;
93	    return refuse();
94	  }
95	}
96	function record(value: unknown): Data {
97	  if (!value || typeof value !== "object" || Array.isArray(value) || types.isProxy(value))
98	    return refuse();
99	  return ownData(value, Object.keys(value));
100	}
101	function array(value: unknown): unknown[] {
102	  if (!Array.isArray(value) || types.isProxy(value)) return refuse();
103	  const ds = Object.getOwnPropertyDescriptors(value);
104	  if (Reflect.ownKeys(ds).length !== value.length + 1 || value.length > 10000)
105	    return refuse("capacity");
106	  return Array.from({ length: value.length }, (_, n) => {
107	    const d = ds[String(n)];
108	    if (!d || !("value" in d) || !d.enumerable) return refuse();
109	    return d.value;
110	  });
111	}
112	function text(value: unknown): string {
113	  if (typeof value !== "string") return refuse();
114	  return value;
115	}
116	function equal(a: unknown, b: unknown, code = "configuration-mismatch") {
117	  if (canonicalJson(a) !== canonicalJson(b)) refuse(code);
118	}
119	function digest(value: string | Uint8Array) {
120	  return createHash("sha256").update(value).digest("hex");
121	}
122	function frozen<T>(value: T): T {
123	  if (value && typeof value === "object") {
124	    for (const x of Object.values(value)) frozen(x);
125	    Object.freeze(value);
126	  }
127	  return value;
128	}
129	function safeData(value: unknown, depth = 0, budget = { nodes: 0 }): unknown {
130	  if (++budget.nodes > 100000 || depth > 128) return refuse("capacity");
131	  if (value === null || typeof value === "string" || typeof value === "boolean") return value;
132	  if (typeof value === "number" && Number.isFinite(value)) return value;
133	  if (Array.isArray(value)) return array(value).map((x) => safeData(x, depth + 1, budget));
134	  const captured = record(value);
135	  if (Object.keys(captured).length > 10000) return refuse("capacity");
136	  return Object.fromEntries(
137	    Object.entries(captured).map(([k, x]) => [k, safeData(x, depth + 1, budget)]),
138	  );
139	}
140	function source(input: unknown) {
141	  const own = ownData(input, ["bytes", "label"], ["bytes"]);
142	  try {
143	    return copySourceBytes({ bytes: own.bytes as Uint8Array }, "manifest", MAX_SOURCE);
144	  } catch (error) {
145	    return artifactError(error);
146	  }
147	}
148	function artifactError(error: unknown): never {
149	  const capacity = [
150	    "manifest source must not exceed 4194304 bytes",
151	    "private-profile-report: JSON must not exceed 100000 nodes",
152	    "private-profile-report: JSON must not exceed depth 128",
153	    "private-profile-report: a JSON container must not exceed 10000 entries",
154	  ];
155	  return refuse(
156	    error instanceof ConformanceArtifactBundleError && capacity.includes(error.message)
157	      ? "capacity"
158	      : "invalid-source",
159	  );
160	}
161	function parsed(bytes: Uint8Array): unknown {
162	  try {
163	    return parseBoundedJson(bytes, "manifest", "private-profile-report");
164	  } catch (error) {
165	    return artifactError(error);
166	  }
167	}
168	function captureAttempt(input: Attempt): Data {
169	  const a = ownData(input, ["outcome", "failureStages", "owners", "sourceDirty"]);
170	  if (
171	    !["running", "failed", "observed"].includes(text(a.outcome)) ||
172	    (a.sourceDirty !== null && typeof a.sourceDirty !== "boolean")
173	  )
174	    refuse();
175	  const failureStages = array(a.failureStages).map(text);
176	  if (
177	    new Set(failureStages).size !== failureStages.length ||
178	    failureStages.some(
179	      (x) => !["execution", "assertion", "cleanup", "credential-check"].includes(x),
180	    )
181	  )
182	    refuse();
183	  const owners = array(a.owners).map((x) => {
184	    const r = ownData(x, ["id", "status", "cleanup", "evidence"]);
185	    if (
186	      !["unobserved", "running", "returned", "failed", "aborted"].includes(text(r.status)) ||
187	      !["not-started", "pending", "reported-complete", "failed", "unknown"].includes(
188	        text(r.cleanup),
189	      ) ||
190	      !["absent", "retained", "withheld-credential"].includes(text(r.evidence))
191	    )
192	      refuse();
193	    return { id: text(r.id), status: r.status, cleanup: r.cleanup, evidence: r.evidence };
194	  });
195	  return { outcome: a.outcome, failureStages, owners, sourceDirty: a.sourceDirty };
196	}
197	function model(
198	  selection: ProfileContractSelection,
199	  configuration: ServedProfileConfiguration,
200	  input: Artifacts,
201	) {
202	  assertCanonicalProfileContractSelection(selection);
203	  if (!["read-update", "transactional"].includes(selection.profile) || selection.history)
204	    refuse("unsupported-selection");
205	  assertSameServedProfileConfiguration(configuration, configuration);
206	  equal([configuration.profile, configuration.history], [selection.profile, selection.history]);
207	  const capturedArtifacts = ownData(
208	    input,
209	    ["kind", "set", "manifest", "fixture", "coverage"],
210	    ["kind"],
211	  );
212	  if (capturedArtifacts.kind !== "read-update" && capturedArtifacts.kind !== "transactional")
213	    refuse("unsupported-selection");
214	  let owners: {
215	    id: string;
216	    bundle: ConformanceArtifactBundle;
217	    ids: readonly string[];
218	    manifest: ConformanceArtifactSource;
219	  }[];
220	  let coverage: Data[];
221	  let artifactDigests: unknown;
222	  if (capturedArtifacts.kind === "read-update") {
223	    if (input.kind !== "read-update") return refuse();
224	    ownData(input, ["kind", "set"]);
225	    assertReadUpdateArtifactSet(input.set);
226	    equal(input.set.selection, selection, "invalid-source");
227	    const sources = copyReadUpdateArtifactSetSources(input.set);
228	    owners = input.set.shards.map((s) => ({
229	      id: s.id,
230	      bundle: s.bundle,
231	      ids: s.scenarioIds,
232	      manifest: sources.manifests[s.source]!,
233	    }));
234	    coverage = input.set.coverage.rows.map((r) => ({ ...r }));
235	    artifactDigests = input.set.digests;
236	  } else {
237	    if (input.kind !== "transactional") return refuse();
238	    ownData(input, ["kind", "manifest", "fixture", "coverage"]);
239	    if (input.kind !== "transactional" || selection.profile !== "transactional")
240	      refuse("unsupported-selection");
241	    const manifest = { bytes: source(input.manifest) },
242	      fixture = { bytes: source(input.fixture) };
243	    const bundle = createCumulativeTransactionalArtifactBundle(selection, { manifest, fixture });
244	    const raw = source(input.coverage),
245	      c = ownData(parsed(raw), [
246	        "coverageVersion",
247	        "claimEligible",
248	        "status",
249	        "transportAdmission",
250	        "rows",
251	      ]);
252	    if (
253	      c.coverageVersion !== 1 ||
254	      c.claimEligible !== false ||
255	      c.status !== "bounded-observation" ||
256	      c.transportAdmission !== "private-exact-available"
257	    )
258	      refuse("invalid-ownership");
259	    coverage = array(c.rows).map((x) => ownData(x, ["id", "wholeContract", "reason", "bindings"]));
260	    equal(
261	      coverage.map((r) => r.id),
262	      bundle.manifest.scenarios.map((r) => r.id),
263	      "invalid-ownership",
264	    );
265	    if (coverage.some((r) => r.wholeContract !== false)) refuse("invalid-ownership");
266	    owners = [
267	      {
268	        id: "transactional-baseline",
269	        bundle,
270	        ids: bundle.manifest.scenarios.map((r) => r.id),
271	        manifest,
272	      },
273	    ];
274	    artifactDigests = { ...bundle.digests, coverageDigest: digest(raw) };
275	  }
276	  if (owners.length > 2) refuse("capacity");
277	  const claimed = new Map<string, string>();
278	  for (const owner of owners) {
279	    equal(owner.bundle.digests.fixtureDigest, configuration.fixtureDigest);
280	    for (const id of owner.ids) {
281	      if (claimed.has(id) || !selection.required.some((r) => r.id === id))
282	        refuse("invalid-ownership");
283	      claimed.set(id, owner.id);
284	    }
285	    const positions = new Map(owner.ids.map((id, n) => [id, n]));
286	    for (const row of owner.bundle.manifest.scenarios) {
287	      const joined = (row.actions ?? row.requests).flatMap((a) =>
288	        a.assertions.map((x) => `${a.id}${selection.profile === "read-update" ? "." : ":"}${x.id}`),
289	      );
290	      if (new Set(joined).size !== joined.length) refuse("invalid-ownership");
291	      const c = coverage.find((r) => r.id === row.id);
292	      if (!c) refuse("invalid-ownership");
293	      equal(c.bindings, [{ scenario: row.id, assertions: joined }], "invalid-ownership");
294	      for (const a of row.actions ?? row.requests)
295	        if (
296	          a.prerequisiteScenario !== undefined &&
297	          (positions.get(a.prerequisiteScenario) ?? Infinity) >= positions.get(row.id)!
298	        )
299	          refuse("invalid-prerequisite");
300	    }
301	  }
302	  return { owners, coverage, claimed, artifactDigests };
303	}
304	type ScenarioPlan = ConformanceArtifactBundle["manifest"]["scenarios"][number];
305	const servedKeys = [
306	  "scope",
307	  "profile",
308	  "history",
309	  "sourceCommit",
310	  "installedPayloadDigest",
311	  "installedContractsDigest",
312	  "policyDigest",
313	  "authenticationDigest",
314	  "fixtureDigest",
315	  "fixtureId",
316	  "capabilities",
317	];
318	const ruReadyKeys = [
319	  "scope",
320	  "profile",
321	  "history",
322	  "payloadIdentity",
323	  "artifactIdentity",
324	  "policyIdentity",
325	  "authenticationIdentity",
326	  "configurationIdentity",
327	];
328	const targetSuffixes = {
329	  batch: "batch",
330	  createBead: "create-bead",
331	  createLink: "create-link",
332	  deleteAlias: "delete-alias",
333	  deleteBead: "delete-bead",
334	  deleteLink: "delete-link",
335	  deleteWhere: "delete-where",
336	  putAlias: "put-alias",
337	  sequence: "sequence",
338	  updateBead: "update-bead",
339	  updateLink: "update-link",
340	  updateWhere: "update-where",
341	};
342	function primitiveHash(value: unknown, length: 40 | 64): string {
343	  const valueText = text(value);
344	  if (!(length === 40 ? /^[a-f0-9]{40}$/ : /^[a-f0-9]{64}$/).test(valueText)) refuse();
345	  return valueText;
346	}
347	// Only called on bounded parsed JSON or already intrinsically captured data.
348	function reportRecord(value: unknown, allowed: readonly string[], required = allowed): Data {
349	  if (value === null || typeof value !== "object" || Array.isArray(value)) refuse("invalid-report");
350	  const r = value as Data;
351	  if (
352	    Object.keys(r).some((k) => !allowed.includes(k)) ||
353	    required.some((k) => !Object.hasOwn(r, k))
354	  )
355	    refuse("invalid-report");
356	  return r;
357	}
358	function reportText(value: unknown): string {
359	  if (typeof value !== "string") refuse("invalid-report");
360	  return value;
361	}
362	function reportHash(value: unknown, length: 40 | 64 = 64): string {
363	  const v = reportText(value);
364	  if (!(length === 40 ? /^[a-f0-9]{40}$/ : /^[a-f0-9]{64}$/).test(v)) refuse("invalid-report");
365	  return v;
366	}
367	function reportArray(value: unknown): unknown[] {
368	  if (!Array.isArray(value)) refuse("invalid-report");
369	  return value;
370	}
371	function servedMetadata(value: unknown, configuration: ServedProfileConfiguration) {
372	  const r = reportRecord(value, servedKeys);
373	  for (const k of ["scope", "profile", "fixtureId"]) reportText(r[k]);
374	  if (
375	    typeof r.history !== "boolean" ||
376	    reportArray(r.capabilities).some((v) => typeof v !== "string")
377	  )
378	    refuse("invalid-report");
379	  reportHash(r.sourceCommit, 40);
380	  for (const k of [
381	    "installedPayloadDigest",
382	    "installedContractsDigest",
383	    "policyDigest",
384	    "authenticationDigest",
385	    "fixtureDigest",
386	  ])
387	    reportHash(r[k]);
388	  equal(r, configuration);
389	}
390	function readyMetadata(
391	  r: Data,
392	  configuration: ServedProfileConfiguration,
393	  runtime: string,
394	  transactional: boolean,
395	) {
396	  reportText(r.scope);
397	  reportText(r.profile);
398	  if (typeof r.history !== "boolean") refuse("invalid-report");
399	  for (const k of ["payloadIdentity", "policyIdentity", "authenticationIdentity"]) reportHash(r[k]);
400	  const artifact = reportText(r.artifactIdentity);
401	  if (!/^development-schema5-[a-f0-9]{64}$/.test(artifact)) refuse("invalid-report");
402	  const actualRuntime = reportHash(
403	    r[transactional ? "runtimeConfigurationIdentity" : "configurationIdentity"],
404	  );
405	  equal(
406	    [
407	      r.scope,
408	      r.profile,
409	      r.history,
410	      r.payloadIdentity,
411	      installedContractsDigest(artifact),
412	      r.policyIdentity,
413	      r.authenticationIdentity,
414	      actualRuntime,
415	    ],
416	    [
417	      configuration.scope,
418	      configuration.profile,
419	      configuration.history,
420	      configuration.installedPayloadDigest,
421	      configuration.installedContractsDigest,
422	      configuration.policyDigest,
423	      configuration.authenticationDigest,
424	      runtime,
425	    ],
426	  );
427	}
428	function wrapperMetadata(
429	  wrapper: Data,
430	  configuration: ServedProfileConfiguration,
431	  runtime: string,
432	  ready: unknown[],
433	  exact: Data,
434	  owner: { ids: readonly string[]; bundle: ConformanceArtifactBundle },
435	) {
436	  if (reportHash(wrapper.sourceCommit, 40) !== configuration.sourceCommit)
437	    refuse("configuration-mismatch");
438	  const sessions = reportArray(wrapper.sessions),
439	    sequence: unknown[] = [];
440	  if (configuration.profile === "read-update") {
441	    servedMetadata(wrapper.configuration, configuration);
442	    if (wrapper.exactConfiguration === undefined) refuse("invalid-report");
443	    // Source has already passed the bounded JSON parser; do not substitute its digest for equality.
444	    if (
445	      wrapper.exactConfiguration === null ||
446	      typeof wrapper.exactConfiguration !== "object" ||
447	      Array.isArray(wrapper.exactConfiguration)
448	    )
449	      refuse("invalid-report");
450	    equal(wrapper.exactConfiguration, exact);
451	    const baseline = reportRecord(wrapper.baselineReceipt, ruReadyKeys);
452	    readyMetadata(baseline, configuration, runtime, false);
453	    sequence.push(baseline);
454	    let last = -1;
455	    for (const value of sessions) {
456	      const r = reportRecord(value, ["scenario", ...ruReadyKeys]);
457	      readyMetadata(r, configuration, runtime, false);
458	      const index = owner.ids.indexOf(reportText(r.scenario));
459	      if (index < 0 || index <= last) refuse("invalid-report");
460	      last = index;
461	      sequence.push(r);
462	    }
463	  } else {
464	    reportText(wrapper.entry);
465	    const baseline = reportRecord(wrapper.baseline, [
466	      "served",
467	      "operationTargets",
468	      "runtimeConfigurationIdentity",
469	      "authorityMode",
470	    ]);
471	    servedMetadata(baseline.served, configuration);
472	    reportText(baseline.authorityMode);
473	    equal(baseline.authorityMode, "canonical");
474	    equal(reportHash(baseline.runtimeConfigurationIdentity), runtime);
475	    const expectedTargets = Object.fromEntries(
476	      Object.entries(targetSuffixes).map(([k, v]) => [k, configuration.scope + "operations/" + v]),
477	    );
478	    const targets = (value: unknown) => {
479	      const r = reportRecord(value, Object.keys(targetSuffixes));
480	      for (const v of Object.values(r)) reportText(v);
481	      equal(r, expectedTargets);
482	    };
483	    targets(baseline.operationTargets);
484	    sequence.push(baseline);
485	    let active = -1,
486	      reopens = 0;
487	    sessions.forEach((value, ordinal) => {
488	      const r = reportRecord(value, [
489	        "event",
490	        "authorityMode",
491	        "runtimeConfigurationIdentity",
492	        "artifactIdentity",
493	        "policyIdentity",
494	        "authenticationIdentity",
495	        "scope",
496	        "profile",
497	        "history",
498	        "claimEligible",
499	        "listenUrl",
500	        "targets",
501	        "payloadIdentity",
502	        "scenario",
503	        "reopen",
504	        "sessionOrdinal",
505	      ]);
506	      readyMetadata(r, configuration, runtime, true);
507	      reportText(r.event);
508	      reportText(r.authorityMode);
509	      if (
510	        typeof r.claimEligible !== "boolean" ||
511	        typeof r.reopen !== "boolean" ||
512	        typeof r.sessionOrdinal !== "number" ||
513	        !Number.isInteger(r.sessionOrdinal)
514	      )
515	        refuse("invalid-report");
516	      equal(
517	        [r.event, r.authorityMode, r.claimEligible],
518	        ["qualification.ready", "canonical", false],
519	      );
520	      if (r.sessionOrdinal !== ordinal) refuse("invalid-report");
521	      const url = reportText(r.listenUrl);
522	      if (
523	        Buffer.byteLength(url) > 8192 ||
524	        !/^http:\/\/127\.0\.0\.1:[1-9][0-9]{0,4}\/$/.test(url) ||
525	        Number(new URL(url).port) > 65535
526	      )
527	        refuse("invalid-report");
528	      targets(r.targets);
529	      const index = owner.ids.indexOf(reportText(r.scenario));
530	      if (index < 0) refuse("invalid-report");
531	      if (r.reopen) {
532	        if (index !== active) refuse("invalid-report");
533	        const plan = owner.bundle.manifest.scenarios.find((p) => p.id === r.scenario)!;
534	        const maximum = (plan.actions ?? plan.requests).filter(
535	          (a) => "operation" in a && a.operation === "transactional.reopen",
536	        ).length;
537	        if (++reopens > maximum) refuse("invalid-report");
538	      } else {
539	        if (index <= active) refuse("invalid-report");
540	        active = index;
541	        reopens = 0;
542	      }
543	      sequence.push(r);
544	    });
545	  }
546	  // Captured supplied metadata must have the identical actual prefix, fields and JSON representation.
547	  equal(sequence, ready);
548	}
549	function stopsAfter(row: Data) {
550	  if (Object.hasOwn(row, "cleanupError")) {
551	    reportText(row.cleanupError);
552	    return true;
553	  }
554	  if (row.prerequisiteFailure !== undefined) {
555	    const p = record(row.prerequisiteFailure);
556	    if (p.phase === "recheck" && p.category !== undefined) return true;
557	  }
558	  return [
559	    "aborted",
560	    "cleanup",
561	    "deadline",
562	    "out-of-scope-target",
563	    "exact-configuration",
564	    "exact-observation",
565	  ].includes(String(row.category));
566	}
567	function rowKind(
568	  row: Data,
569	  plan: ScenarioPlan | undefined,
570	  owner: { ids: readonly string[]; bundle: ConformanceArtifactBundle },
571	  prior: readonly Data[],
572	): boolean {
573	  const exchanges = array(row.exchanges),
574	    actions = row.actions === undefined ? [] : array(row.actions);
575	  if (Object.hasOwn(row, "cleanupError")) reportText(row.cleanupError);
576	  if (row.prerequisiteFailure !== undefined) {
577	    if (!plan || row.state !== "harness-error" || row.category !== "not-run")
578	      refuse("invalid-report");
579	    const p = reportRecord(
580	      row.prerequisiteFailure,
581	      ["id", "requirements", "reason", "phase", "category"],
582	      ["id", "requirements", "reason", "phase"],
583	    );
584	    const id = reportText(p.id),
585	      phase = reportText(p.phase);
586	    reportText(p.reason);
587	    const declared = (plan.actions ?? plan.requests).some((a) => a.prerequisiteScenario === id);
588	    const before = prior.find((r) => r.id === id),
589	      metadata = owner.bundle.catalog.scenarios.find((r) => r.id === id);
590	    if (
591	      !declared ||
592	      !metadata ||
593	      !owner.ids.includes(id) ||
594	      !["initial", "recheck"].includes(phase)
595	    )
596	      refuse("invalid-report");
597	    equal(
598	      p.requirements,
599	      metadata.requirements.map(({ source, anchor }) => `${source}${anchor}`),
