692	function joinedOutcome(
693	  row: Data,
694	  plan: ConformanceArtifactBundle["manifest"]["scenarios"][number] | undefined,
695	) {
696	  if (!plan) {
697	    if (array(row.exchanges).length || (row.actions !== undefined && array(row.actions).length))
698	      refuse("invalid-report");
699	    return null;
700	  }
701	  const lanes = {
702	    http: array(row.exchanges),
703	    other: row.actions === undefined ? [] : array(row.actions),
704	  };
705	  const authored = plan.actions ?? plan.requests;
706	  const httpRows = lanes.http.map(record),
707	    other = lanes.other.map(record);
708	  // A client action may emit a same-ID incidental exchange; it cannot supply
709	  // the client action's assertion lane. Truly unknown/duplicate IDs still refuse.
710	  const httpIds = httpRows.map((x) => text(record(x.request).id));
711	  if (
712	    new Set(httpIds).size !== httpIds.length ||
713	    httpIds.some((id) => !authored.some((a) => a.id === id))
714	  )
715	    refuse("invalid-report");
716	  for (const row of httpRows) {
717	    const assertions = array(row.assertions).map(record);
718	    if (
719	      new Set(assertions.map((x) => x.id)).size !== assertions.length ||
720	      assertions.some((x) => typeof x.id !== "string" || typeof x.passed !== "boolean")
721	    )
722	      refuse("invalid-report");
723	  }
724	  if (
725	    new Set(other.map((x) => record(x.action).id)).size !== other.length ||
726	    other.some((x) => {
727	      const actual = record(x.action),
728	        declared = authored.find((a) => a.id === actual.id);
729	      return (
730	        !declared ||
731	        !("family" in declared) ||
732	        declared.family === "http" ||
733	        declared.family !== actual.family
734	      );
735	    })
736	  )
737	    refuse("invalid-report");
738	  for (const [records, http] of [
739	    [httpRows, true],
740	    [other, false],
741	  ] as const) {
742	    let last = -1;
743	    for (const value of records) {
744	      const actual = record(value[http ? "request" : "action"]),
745	        index = authored.findIndex((a) => a.id === actual.id),
746	        declared = authored[index]!;
747	      if (index <= last) refuse("invalid-report");
748	      last = index;
749	      if (
750	        !http &&
751	        actual.operation !== undefined &&
752	        (!("operation" in declared) || declared.operation !== actual.operation)
753	      )
754	        refuse("invalid-report");
755	      const assertions = array(value.assertions).map(record);
756	      if (
757	        new Set(assertions.map((a) => a.id)).size !== assertions.length ||
758	        assertions.some((a) => typeof a.id !== "string" || typeof a.passed !== "boolean")
759	      )
760	        refuse("invalid-report");
761	      // Incidental same-ID non-HTTP exchanges never supply the authored assertion lane.
762	      if (
763	        (!http || !("family" in declared) || declared.family === "http") &&
764	        assertions.some((a) => !declared.assertions.some((x) => x.id === a.id))
765	      )
766	        refuse("invalid-report");
767	    }
768	  }
769	  if (["not-run", "not-implemented"].includes(String(row.category))) return null;
770	  const values: (boolean | null)[] = [];
771	  for (const action of plan.actions ?? plan.requests) {
772	    const http = !("family" in action) || action.family === "http";
773	    const matching = lanes[http ? "http" : "other"]
774	      .map(record)
775	      .filter((x) => (http ? record(x.request).id : record(x.action).id) === action.id);
776	    if (matching.length > 1) refuse("invalid-report");
777	    const assertions = matching.length ? array(matching[0]!.assertions).map(record) : [];
778	    if (
779	      new Set(assertions.map((x) => x.id)).size !== assertions.length ||
780	      assertions.some(
781	        (x) => !action.assertions.some((a) => a.id === x.id) || typeof x.passed !== "boolean",
782	      )
783	    )
784	      refuse("invalid-report");
785	    for (const authored of action.assertions)
786	      values.push(
787	        (assertions.find((x) => x.id === authored.id)?.passed as boolean | undefined) ?? null,
788	      );
789	  }
790	  return values.some((x) => x === false)
791	    ? false
792	    : values.some((x) => x === null) || !values.length
793	      ? null
794	      : true;
795	}
