        "kind",
        "bindingStatus",
        "configuration",
        "claimEligible",
        "qualificationReady",
        "requestedProfile",
        "declaredSourceCommit",
        "artifactDigests",
        "requiredIds",
        "owners",
        "observations",
        "attempt",
        "limitations",
      ]);
