        obs = array(e.observations),
        owners = array(e.owners);
      if (
        ids.length !== 130 ||
        new Set(ids).size !== 130 ||
        obs.length !== ids.length ||
        obs.some((x) => x !== null) ||
        owners.length !== ids.length
      )
        refuse();
