        "kind",
        "claimEligible",
        "qualificationReady",
        "profile",
        "history",
        "configuration",
        "catalogDigests",
        "artifactDigests",
        "requiredIds",
        "retiredIds",
        "requirements",
        "nonRequiredReportRows",
        "reports",
        "attempt",
        "unresolvedConditions",
        "limitations",
