        e.carrierVersion !== 1 ||
        e.kind !== "private-profile-evidence" ||
        e.claimEligible !== false ||
        e.qualificationReady !== false ||
        e.history !== false ||
        !["read-update", "transactional"].includes(text(e.profile))
