457	/** Safe attempt evidence is separate from the all-checks-passed set summary. */
458	export function createArtifactEvidenceWriter(
459	  set: ReadUpdateArtifactSet,
460	  sourceCommit: string,
461	  filename: string | undefined,
462	  credentialValues: readonly string[],
463	) {
464	  assertReadUpdateArtifactSet(set);
465	  const credentials = [...credentialValues];
466	  if (!/^[a-f0-9]{40}$/.test(sourceCommit) || credentials.some((s) => !s))
467	    throw Error("invalid evidence writer identity");
468	  if (
469	    filename &&
470	    [
471	      filename,
472	      `${filename}.attempt.json`,
473	      ...set.shards.map((s) => `${filename}.${s.id}.json`),
474	    ].some(existsSync)
475	  )
476	    throw Error("evidence output already exists; choose a fresh attempt path");
477	  type Cleanup = "not-started" | "pending" | "complete" | "failed";
478	  const rows = set.shards.map((s) => ({
479	    id: s.id,
480	    source: s.source,
481	    manifestDigest: s.bundle.digests.manifestDigest,
482	    status: "unobserved" as "unobserved" | "running" | "returned" | "aborted" | "failed",
483	    cleanup: "not-started" as Cleanup,
484	    evidence: "absent" as "absent" | "retained" | "withheld-credential",
485	    resultDigest: undefined as string | undefined,
486	    writtenReportDigest: undefined as string | undefined,
487	    writtenReportBytes: undefined as number | undefined,
488	    timing: undefined as
489	      | {
490	          budgetRemainingMsAtStart: number;
491	          elapsedMs: number;
492	          outcome: "running" | "pass" | "aborted" | "failed";
493	        }
494	      | undefined,
495	  }));
496	  const snapshots = new Map<number, Record<string, unknown>>();
497	  const profilePath =
498	    filename && filename === process.env.BDP_CUMULATIVE_REPORT_PATH
499	      ? process.env.BDP_PRIVATE_PROFILE_EVIDENCE_PATH
500	      : undefined;
501	  const sidecar = profilePath
502	    ? createPrivateProfileSidecarWriter({
503	        base: profilePath,
504	        profile: "read-update",
505	        credentialValues: credentials,
506	        unboundSet: set,
507	      })
508	    : undefined;
509	  let profileConfiguration: ArtifactObservation["configuration"] | undefined;
510	  const profileBindings = new Map<number, ArtifactObservation["configuration"]>();
511	  const profileBytes = new Map<number, Uint8Array>();
512	  let failed = false;
513	  type FailureStage = "execution" | "assertion" | "cleanup" | "credential-check";
514	  const failureStages: FailureStage[] = [];
515	  function safeJson(value: unknown) {
516	    const text = JSON.stringify(value, null, 2);
517	    function inspect(v: unknown): boolean {
518	      if (typeof v === "string") {
519	        const candidates = [v];
520	        if (v.length % 4 === 0 && /^[A-Za-z0-9+/]+={0,2}$/.test(v))
521	          candidates.push(Buffer.from(v, "base64").toString("utf8"));
522	        try {
523	          candidates.push(decodeURIComponent(v));
524	        } catch {
525	          /* Non-URI strings remain checked literally. */
526	        }
527	        return candidates.some((candidate) =>
528	          credentials.some((secret) => candidate.includes(secret)),
529	        );
530	      }
531	      return (
532	        v !== null &&
533	        typeof v === "object" &&
534	        Object.entries(v).some(([key, value]) => inspect(key) || inspect(value))
535	      );
536	    }
537	    if (inspect(JSON.parse(text))) throw Error("credential-bearing evidence withheld");
538	    return text;
539	  }
540	  // Cleanup metadata replaces a complete file atomically. A failed replacement
541	  // leaves previously returned genuine evidence intact (not a power-loss claim).
542	  function replaceFile(destination: string, encoded: string) {
543	    const temporary = `${destination}.pending-${randomUUID()}`;
544	    try {
545	      writeFileSync(temporary, encoded, { flag: "wx", mode: 0o600 });
546	      renameSync(temporary, destination);
547	    } catch (error) {
548	      try {
549	        rmSync(temporary, { force: true });
550	      } catch (cleanup) {
551	        throw new AggregateError([error, cleanup], "evidence replacement and cleanup failed", {
552	          cause: error,
553	        });
554	      }
555	      throw error;
556	    }
557	  }
558	  function ledger(outcome: "running" | "failed" | "observed", stage?: FailureStage) {
559	    if (stage && !failureStages.includes(stage)) failureStages.push(stage);
560	    const value = {
561	      claimEligible: false,
562	      outcome,
563	      ...(failureStages.length
564	        ? { failureStage: failureStages[0], failureStages: [...failureStages] }
565	        : {}),
566	      sourceCommit,
567	      ...set.digests,
568	      ...requiredObservations(
569	        set,
570	        set.shards.map(
571	          (_, index) => snapshots.get(index)?.result as ConformanceRunResult | undefined,
572	        ),
573	      ),
574	      shards: rows.map((r) => ({
575	        ...r,
576	        ...(r.evidence === "retained" && filename ? { report: `${filename}.${r.id}.json` } : {}),
577	      })),
578	    };
579	    const encoded = safeJson(value);
580	    if (filename) replaceFile(`${filename}.attempt.json`, encoded);
581	    if (sidecar) sidecar.writeAttempt(profileEvidence(value.outcome));
582	    return value;
583	  }
584	  function persist(index: number) {
585	    const snapshot = snapshots.get(index);
586	    if (!snapshot) return;
587	    snapshot.cleanupStatus = rows[index]!.cleanup;
588	    snapshot.cleanupComplete = rows[index]!.cleanup === "complete";
589	    const encoded = safeJson(snapshot);
590	    if (filename) replaceFile(`${filename}.${rows[index]!.id}.json`, encoded);
591	    if (sidecar) profileBytes.set(index, Buffer.from(encoded));
592	    rows[index]!.evidence = "retained";
593	    rows[index]!.writtenReportDigest = createHash("sha256").update(encoded).digest("hex");
594	    rows[index]!.writtenReportBytes = Buffer.byteLength(encoded);
595	  }
596	  function profileEvidence(outcome: "running" | "failed" | "observed") {
597	    const attempt = {
598	      outcome,
599	      failureStages: [...failureStages],
600	      owners: rows.map((r) => ({
601	        id: r.id,
602	        status: r.status,
603	        cleanup: r.cleanup === "complete" ? "reported-complete" : r.cleanup,
604	        evidence: r.evidence,
605	      })),
606	      sourceDirty:
607	        typeof snapshots.get(0)?.sourceDirty === "boolean"
608	          ? (snapshots.get(0)!.sourceDirty as boolean)
609	          : null,
610	    };
611	    if (!profileConfiguration)
612	      return {
613	        attemptVersion: 1,
614	        kind: "private-profile-attempt-unbound",
615	        bindingStatus: "unbound",
616	        configuration: null,
617	        claimEligible: false,
618	        qualificationReady: false,
619	        requestedProfile: "read-update",
620	        declaredSourceCommit: sourceCommit,
621	        artifactDigests: set.digests,
622	        requiredIds: set.requirements.map((r) => r.id),
623	        owners: set.requirements,
624	        observations: set.requirements.map(() => null),
625	        attempt,
626	        limitations: [
627	          "no returned served configuration yet",
628	          "not a bound carrier, target observation, admission or qualification",
629	        ],
630	      };
631	    return assembleProfileEvidence(
632	      set.selection,
633	      profileConfiguration,
634	      { kind: "read-update", set },
635	      set.shards.map((shard, index) => {
636	        const bytes = profileBytes.get(index),
637	          snapshot = snapshots.get(index),
638	          configuration = profileBindings.get(index);
639	        if (!bytes || !snapshot || !configuration) return null;
640	        return {
641	          ownerId: shard.id,
642	          sourceCommit,
643	          configuration,
644	          runtimeConfigurationIdentity: String(
645	            (snapshot.baselineReceipt as Record<string, unknown>).configurationIdentity,
646	          ),
647	          exactConfiguration: snapshot.exactConfiguration,
648	          ready: [snapshot.baselineReceipt, ...(snapshot.sessions as unknown[])],
649	          reportSource: { bytes },
650	          expectedReportSha256: createHash("sha256").update(bytes).digest("hex"),
651	          lifecycle: {
652	            cleanup:
653	              rows[index]!.cleanup === "complete"
654	                ? ("reported-complete" as const)
655	                : rows[index]!.cleanup === "failed"
656	                  ? ("failed" as const)
657	                  : ("pending" as const),
658	          },
659	        };
660	      }),
661	      attempt,
662	    );
663	  }
664	  const api = {
665	    start(index: number) {
666	      rows[index]!.status = "running";
667	      ledger("running");
668	    },
669	    acquired(index: number) {
670	      rows[index]!.cleanup = "pending";
671	      ledger("running");
672	    },
673	    returned(index: number, report: ArtifactObservation) {
674	      // Only known wrapper fields accompany the genuine runner result. Never retain
675	      // thrown errors, child stderr, resolver functions or arbitrary wrapper keys.
676	      const extra = report as ArtifactObservation & {
677	        observations?: unknown;
678	        setupObservations?: unknown;
679	        nativeReadObservations?: unknown;
680	        sourceDirty?: boolean;
681	      };
682	      const snapshot = {
683	        claimEligible: false,
684	        sourceCommit: report.sourceCommit,
685	        configuration: report.configuration,
686	        baselineReceipt: readySummary(report.baselineReceipt),
687	        sessions: report.sessions.map((s) => ({ scenario: s.scenario, ...readySummary(s) })),
688	        catalogSources: report.catalogSources,
689	        plannedManifestDigest: report.plannedManifestDigest,
690	        plannedIds: report.plannedIds,
691	        requiredIds: report.requiredIds,
692	        exactConfiguration: {
693	          scope: report.exactConfiguration.scope,
694	          profile: report.exactConfiguration.profile,
695	          routes: report.exactConfiguration.routes,
696	          maximumRequestHeaderBytes: report.exactConfiguration.maximumRequestHeaderBytes,
697	          maximumRequestBodyBytes: report.exactConfiguration.maximumRequestBodyBytes,
698	          credentialHandles: report.exactConfiguration.credentialHandles,
699	          defaultCredentialRef: report.exactConfiguration.defaultCredentialRef,
700	        },
701	        result: report.result,
702	        observations: extra.observations,
703	        setupObservations: extra.setupObservations,
704	        nativeReadObservations: extra.nativeReadObservations,
705	        sourceDirty: extra.sourceDirty,
706	      };
707	      let captured: Record<string, unknown>;
708	      try {
709	        // Capture once: later caller mutation cannot corrupt a retained child report.
710	        captured = JSON.parse(safeJson(snapshot));
711	      } catch (error) {
712	        rows[index]!.status = "failed";
713	        rows[index]!.evidence = "withheld-credential";
714	        failed = true;
715	        ledger("failed", "credential-check");
716	        throw error;
717	      }
718	      if (sidecar) {
719	        assertSameServedProfileConfiguration(report.configuration, report.configuration);
720	        if (profileConfiguration)
721	          assertSameServedProfileConfiguration(profileConfiguration, report.configuration);
722	        else profileConfiguration = report.configuration;
723	        profileBindings.set(index, report.configuration);
724	      }
725	      snapshots.set(index, captured);
726	      rows[index]!.status = "returned";
727	      rows[index]!.resultDigest = digest(report.result);
728	      persist(index);
729	      ledger("running");
730	    },
731	    cleaned(index: number, status: "complete" | "failed") {
732	      rows[index]!.cleanup = status;
733	      if (status === "failed") {
734	        rows[index]!.status = "failed";
735	        failed = true;
736	      }
737	      persist(index);
738	      ledger(failed ? "failed" : "running", status === "failed" ? "cleanup" : undefined);
739	    },
740	    failed(index: number, aborted: boolean) {
741	      rows[index]!.status = aborted ? "aborted" : "failed";
742	      failed = true;
743	      ledger("failed", "execution");
744	    },
745	    timed(index: number, timing: NonNullable<(typeof rows)[number]["timing"]>) {
746	      rows[index]!.timing = {
747	        budgetRemainingMsAtStart: timing.budgetRemainingMsAtStart,
748	        elapsedMs: timing.elapsedMs,
749	        outcome: timing.outcome,
750	      };
751	      ledger(failed ? "failed" : "running");
752	    },
753	    failedSet() {
754	      failed = true;
755	      ledger("failed", "assertion");
756	    },
757	    succeeded(summary: Record<string, unknown>) {
758	      if (
759	        failed ||
760	        rows.some(
761	          (r) => r.status !== "returned" || r.cleanup !== "complete" || r.evidence !== "retained",
762	        )
763	      )
764	        throw Error("cannot publish incomplete artifact evidence");
765	      const encoded = safeJson({
766	        ...summary,
767	        writtenReports: rows.map((r) => ({
768	          id: r.id,
769	          resultDigest: r.resultDigest,
770	          ...(filename
771	            ? {
772	                report: `${filename}.${r.id}.json`,
773	                writtenReportDigest: r.writtenReportDigest,
774	                writtenReportBytes: r.writtenReportBytes,
775	              }
776	            : {}),
777	        })),
778	      });
779	      ledger("observed");
780	      if (filename) replaceFile(filename, encoded);
781	      if (sidecar) sidecar.writeSummary(profileEvidence("observed"));
782	    },
783	  };
784	  ledger("running");
785	  return api;
786	}
787	export type ArtifactEvidenceWriter = ReturnType<typeof createArtifactEvidenceWriter>;
