2	import { canonicalJson } from "../src/canonical-json.js";
3	import { createHash } from "node:crypto";
4	import { types } from "node:util";
5	import { isProtocolProfile, type ProtocolProfile } from "@bdp/protocol";
6	import {
7	  type ConformanceArtifactSource,
8	  type ConformanceFixture,
9	  copySourceBytes,
10	  CUMULATIVE_MANIFEST_MAX_BYTES,
11	  parseBoundedJson,
12	  parseFixtureJson,
13	  validateFixtureOraclePointers,
14	} from "../src/artifact-bundle.js";
15	import { parseExecutableScenarioManifest } from "../src/executable-manifest.js";
16	import { isCanonicalScope } from "../src/runner.js";
17	import { profileIncludes } from "../src/selection.js";
18	import {
19	  assertCanonicalProfileContractSelection,
20	  type ProfileContractSelection,
21	} from "../src/profile-contract-selection.js";
22	export {
23	  loadProfileContractSelection,
24	  inspectProfileContractSourcesForTest,
25	  type ProfileContractSelection,
26	} from "../src/profile-contract-selection.js";
27	
28	const configurations = new WeakMap<object, ConformanceFixture>();
29	
30	/**
31	 * Non-secret identity inputs captured from ONE installed service/fixture by a
32	 * trusted launcher. Digests follow existing SHA-256 artifact conventions.
