210	 * Uses the real executable manifest parser; no second action/fixture language.
211	 * ready-unexecuted is structural readiness, conditional on the runner enforcing
212	 * matching exact transport configuration before observing a non-Read target.
213	 * TX structural readiness does not admit TX exact transport, which remains a
214	 * separate implementation gate. It supplies no execution admission or observation.
215	 * Missing applicability is a review obligation, never a waiver.
216	 */
217	export function planProfileExecution(
218	  selection: ProfileContractSelection,
219	  configuration: ServedProfileConfiguration,
220	  execution?: {
221	    readonly configuration: ServedProfileConfiguration;
222	    readonly manifest: ConformanceArtifactSource;
223	  },
224	): ProfileExecutionPlan {
225	  assertCanonicalProfileContractSelection(selection);
226	  const fixture = assertBoundConfiguration(configuration);
227	  const bound = configuration;
228	  if (bound.profile !== selection.profile || bound.history !== selection.history)
229	    throw new Error("selection and served configuration disagree");
230	  let source: ReturnType<typeof snapshotSource> | undefined;
231	  if (execution !== undefined) {
232	    const captured = ownData(execution, ["configuration", "manifest"]);
233	    assertSameServedProfileConfiguration(
234	      bound,
235	      captured.configuration as ServedProfileConfiguration,
236	    );
237	    source = snapshotSource(
238	      captured.manifest,
239	      "manifest",
