253	    manifest &&
254	    source &&
255	    !(manifest.catalogId === "read-update-v1" && manifest.manifestVersion === 2)
256	  )
257	    copySourceBytes({ bytes: source.bytes }, "manifest"); // Other carriers retain the ordinary source budget.
258	  if (manifest) validateFixtureOraclePointers(manifest, fixture);
259	  // The current ordinary artifact factory accepts read-v1. The runner permits
260	  // v1 non-Read lacks the exact execution binding and remains unsupported.
261	  // v2 Read+Update requires matching exact execution configuration; this plan
262	  // is not execution, qualification or proof that such a target was observed.
263	  // Separate cumulative RU/TX factories support baseline (no History) only.
264	  // TX carrier planning does not enable the still-closed exact transport gate.
265	  const carrierBlocker =
266	    manifest === undefined ||
267	    (manifest.catalogId === "transactional-v1" &&
268	      !bound.history &&
269	      manifest.manifestVersion === 2 &&
270	      bound.profile === "transactional") ||
271	    (manifest.catalogId === "read-update-v1" &&
272	      !bound.history &&
273	      manifest.manifestVersion === 2 &&
274	      bound.profile === "read-update") ||
275	    (manifest.catalogId === "read-v1" &&
276	      (bound.profile === "read" ||
277	        (bound.profile === "read-update" && manifest.manifestVersion === 2)))
278	      ? undefined
279	      : `current normative artifact/runner carrier does not support ${manifest.catalogId} version ${manifest.manifestVersion} on ${bound.profile}`;
280	  const required = new Map(selection.required.map((row) => [row.id, row]));
281	  for (const row of manifest?.scenarios ?? []) {
282	    if (selection.retiredIds.includes(row.id))
283	      throw new Error(`manifest includes retired requirement: ${row.id}`);
284	    const contract = required.get(row.id);
285	    if (
286	      !contract ||
287	      !profileIncludes(bound.profile, row.requiredProfile) ||
288	      contract.requiredProfile !== row.requiredProfile
289	    )
290	      throw new Error(`manifest row is not a selected requirement: ${row.id}`);
291	    if (row.setup.fixture !== bound.fixtureId)
292	      throw new Error(`manifest fixture mismatch: ${row.id}`);
293	  }
294	  const declared = new Set(bound.capabilities);
295	  const executable = new Map(manifest?.scenarios.map((row) => [row.id, row]));
296	  const positions = new Map(selection.catalog.scenarios.map((row, index) => [row.id, index]));
297	  const earlier = (id: string, dependency: string) =>
298	    (positions.get(dependency) ?? Infinity) < (positions.get(id) ?? -1);
299	  const dependencies = new Map(
300	    [...executable].map(([id, row]) => [
301	      id,
302	      [
303	        ...new Set(
304	          (row.actions ?? row.requests).flatMap((action) =>
305	            action.prerequisiteScenario === undefined ? [] : [action.prerequisiteScenario],
306	          ),
307	        ),
308	      ],
309	    ]),
310	  );
311	  const base = (id: string) => {
312	    const row = executable.get(id);
313	    const missingApplicability =
314	      row?.applicability.requires.filter((key) => !declared.has(key)) ?? [];
315	    const missingSetup = row?.setup.requires.filter((key) => !declared.has(key)) ?? [];
316	    return { row, missingApplicability, missingSetup };
317	  };
318	  // Dependencies must precede their consumer in canonical catalog order.
319	  // Resolve each row once in that order: shared DAGs stay linear, and missing,
320	  // retired or later dependencies (including cycles) remain unavailable.
321	  const dependencyReady = new Map<string, boolean>();
322	  for (const { id } of selection.catalog.scenarios) {
323	    if (!required.has(id)) continue;
324	    const { row, missingApplicability, missingSetup } = base(id);
325	    dependencyReady.set(
326	      id,
327	      !!row &&
328	        !missingApplicability.length &&
329	        !missingSetup.length &&
330	        (dependencies.get(id) ?? []).every(
331	          (dependency) => earlier(id, dependency) && dependencyReady.get(dependency) === true,
332	        ),
333	    );
334	  }
335	  const requirements: PlannedProfileRequirement[] = selection.required.map(({ id }) => {
336	    const { row, missingApplicability, missingSetup } = base(id);
337	    const blockedPrerequisites = (dependencies.get(id) ?? []).filter(
338	      (dependency) => !earlier(id, dependency) || dependencyReady.get(dependency) !== true,
339	    );
340	    return {
341	      id,
342	      missingApplicability,
343	      missingSetup,
344	      blockedPrerequisites,
345	      readiness: !row
346	        ? "unplanned"
347	        : carrierBlocker
348	          ? "carrier-unsupported"
349	          : blockedPrerequisites.length
350	            ? "prerequisite-blocked"
351	            : missingApplicability.length
352	              ? "applicability-unresolved"
353	              : missingSetup.length
354	                ? "setup-unavailable"
355	                : "ready-unexecuted",
356	    };
357	  });
358	  return freeze({
359	    claimEligible: false,
360	    configuration: bound,
361	    catalogDigests: selection.catalogDigests,
362	    ...(source === undefined ? {} : { manifestDigest: digest(source.bytes) }),
363	    ...(carrierBlocker === undefined ? {} : { carrierBlocker }),
364	    ...(bound.profile === "transactional"
365	      ? { transportAdmission: "private-exact-available" as const }
366	      : {}),
367	    retiredIds: selection.retiredIds,
368	    requirements,
369	    unobservedIds: requirements.map(({ id }) => id),
370	  });
371	}
372	
373	function digest(value: string | Uint8Array): string {
374	  return createHash("sha256").update(value).digest("hex");
375	}
376	function freeze<T>(value: T): T {
377	  if (value && typeof value === "object") {
378	    for (const member of Object.values(value)) freeze(member);
379	    Object.freeze(value);
380	  }
381	  return value;
382	}
