355	function jsonPointer(value: unknown, pointer: string): unknown {
356	  if (pointer === "") return value;
357	  let current: unknown = value;
358	  for (const part of pointer.slice(1).split("/")) {
359	    if (typeof current !== "object" || current === null) return undefined;
360	    const key = part.replace(/~1/g, "/").replace(/~0/g, "~");
361	    if (Array.isArray(current)) {
362	      if (!/^(?:0|[1-9]\d*)$/.test(key)) return undefined;
363	      current = current[Number(key)];
364	    } else {
365	      if (!Object.hasOwn(current, key)) return undefined;
366	      current = (current as Record<string, unknown>)[key];
367	    }
368	  }
369	  return current;
370	}
