404	  } catch {
405	    throw new ConformanceArtifactBundleError(`${kind} source bytes must be a Uint8Array`);
406	  }
407	  if (byteLength > maximumBytes) {
408	    throw new ConformanceArtifactBundleError(
409	      `${kind} source must not exceed ${maximumBytes} bytes`,
410	    );
411	  }
412	  const copy = new Uint8Array(byteLength);
413	  Reflect.apply(UINT8_ARRAY_SET, copy, [bytes]);
414	  return copy;
