446	function assertJsonComplexity(value: unknown, label: string): void {
447	  const pending: Array<{ readonly value: unknown; readonly depth: number }> = [{ value, depth: 0 }];
448	  let nodes = 0;
449	  while (pending.length > 0) {
450	    const current = pending.pop();
451	    if (current === undefined) continue;
452	    nodes += 1;
453	    if (nodes > ARTIFACT_MAX_JSON_NODES)
454	      throw new ConformanceArtifactBundleError(
455	        `${label}: JSON must not exceed ${ARTIFACT_MAX_JSON_NODES} nodes`,
456	      );
457	    if (current.depth > ARTIFACT_MAX_JSON_DEPTH)
458	      throw new ConformanceArtifactBundleError(
459	        `${label}: JSON must not exceed depth ${ARTIFACT_MAX_JSON_DEPTH}`,
460	      );
461	    if (typeof current.value === "number" && !Number.isFinite(current.value))
462	      throw new ConformanceArtifactBundleError(`${label}: JSON numbers must be finite`);
463	    if (typeof current.value !== "object" || current.value === null) continue;
464	    const children = Array.isArray(current.value)
465	      ? current.value
466	      : Object.values(current.value as Record<string, unknown>);
467	    if (children.length > ARTIFACT_MAX_CONTAINER_ENTRIES)
468	      throw new ConformanceArtifactBundleError(
469	        `${label}: a JSON container must not exceed ${ARTIFACT_MAX_CONTAINER_ENTRIES} entries`,
470	      );
471	    for (const child of children) pending.push({ value: child, depth: current.depth + 1 });
472	  }
473	}
