    inventory.version !== 1 ||
    inventory.claimEligible !== false ||
    !Array.isArray(inventory.rows) ||
    inventory.rows.length !== selection.required.length
  )
    throw Error(
      "coverage must contain the complete canonical required inventory with claimEligible false",
    );
