342	async function runMatrix(
343	  options: ScenarioRunOptions,
344	  transactional: boolean,
345	  context?: TransactionalRunContext,
346	): Promise<ConformanceRunResult> {
347	  const runOptions = snapshotRunOptions(options);
348	  const branded = isCumulativeTransactionalArtifactBundle(runOptions.artifactBundle);
349	  if (transactional ? !branded || runOptions.profile !== "transactional" : branded)
350	    throw new ConformanceRunnerError(
351	      "private Transactional bundle requires its matching private runner and profile",
352	    );
353	  validateRunOptions(runOptions, transactional);
354	  const { catalog, manifest } = runOptions.artifactBundle;
355	  const metadata = selectApplicableScenariosForProfile(catalog, runOptions.profile);
356	  const allCatalogIds = new Set(catalog.scenarios.map(({ id }) => id));
357	  const unknownPlan = manifest.scenarios.find(({ id }) => !allCatalogIds.has(id));
358	  if (unknownPlan !== undefined)
359	    throw new ConformanceRunnerError(`executable plan '${unknownPlan.id}' has no catalog metadata`);
360	  const byId = new Map(manifest.scenarios.map((scenario) => [scenario.id, scenario]));
361	  let selected =
362	    runOptions.scenarioFilter === undefined
363	      ? metadata
364	      : metadata.filter(({ id }) => id.includes(runOptions.scenarioFilter as string));
365	  if (runOptions.scenarioFilter !== undefined && selected.length === 0)
366	    throw new ConformanceRunnerError("scenarioFilter matched no applicable scenarios");
367	  if (runOptions.scenarioSelection !== undefined) {
368	    const applicable = new Set(metadata.map(({ id }) => id));
369	    const missing = runOptions.scenarioSelection.filter((id) => !applicable.has(id));
370	    if (missing.length > 0)
371	      throw new ConformanceRunnerError(
372	        `scenarioSelection names scenarios that are unknown or inapplicable: ${missing.join(", ")}`,
373	      );
374	    const requested = new Set(runOptions.scenarioSelection);
375	    // Catalog order is preserved: the selection names membership, not sequence.
376	    selected = metadata.filter(({ id }) => requested.has(id));
377	  }
378	  preflightExactPlans(
379	    selected.flatMap(({ id }) => byId.get(id) ?? []),
380	    runOptions,
381	  );
382	  const results: ScenarioRunResult[] = [];
383	  const resultsById = new Map<string, ScenarioRunResult>();
384	  for (const [index, scenario] of selected.entries()) {
385	    if (runOptions.signal?.aborted === true) {
386	      for (const remaining of selected.slice(index)) results.push(stoppedScenarioResult(remaining));
387	      break;
388	    }
389	    const plan = byId.get(scenario.id);
390	    const scenarioResult =
391	      plan === undefined
392	        ? missingPlanResult(scenario)
393	        : (prerequisiteResultBeforeRun(scenario, plan, resultsById, catalog) ??
394	          (await runScenario(scenario, plan, runOptions, context)));
395	    results.push(scenarioResult);
396	    resultsById.set(scenarioResult.id, scenarioResult);
397	    if (mustStopMatrixAfter(scenarioResult)) {
398	      for (const remaining of selected.slice(results.length))
399	        results.push(stoppedScenarioResult(remaining));
400	      break;
401	    }
402	  }
403	  const common = {
404	    scope: runOptions.scope,
405	    profile: runOptions.profile,
406	    seed: runOptions.seed,
407	    selectedScenarioIds: selected.map(({ id }) => id),
408	    ...(runOptions.scenarioFilter === undefined
409	      ? {}
410	      : { scenarioFilter: runOptions.scenarioFilter }),
411	    ...(runOptions.scenarioSelection === undefined
412	      ? {}
413	      : { scenarioSelection: runOptions.scenarioSelection }),
414	    artifacts: runOptions.artifactBundle.digests,
415	    declarations: {
416	      targetLabel: runOptions.declaredTargetLabel,
417	      ...(runOptions.artifactBundle.manifest.manifestVersion === 2 &&
418	      runOptions.exactExecution !== undefined
419	        ? { exactConfigurationDigest: exactConfigurationDigest(runOptions.exactExecution) }
420	        : {}),
421	    },
422	    claimEligible: false as const,
423	  };
